import {
  Group,
  Mesh,
  PlaneGeometry,
  BoxGeometry,
  PointLight,
  Texture,
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial,
} from 'three/webgpu';
import {
  uv,
  vec2,
  color,
  texture,
  fract,
  sin,
  dot,
  length,
  smoothstep,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const palette = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'hub-collection-card-2';

  const inner = new Group();
  root.add(inner);

  // ---- dimensions -------------------------------------------------
  const cardW = 2.1;
  const cardH = 2.5;
  const frameDepth = 0.08;

  // ---- machined-metal frame (backdrop depth plane) ------------------
  const frameGeo = new BoxGeometry(cardW, cardH, frameDepth);
  const frameMaterial = new MeshStandardNodeMaterial();
  const frameUv = uv();
  const frameGradient = color(palette.surface).mix(color(palette.ink), frameUv.y);
  frameMaterial.colorNode = frameGradient;
  frameMaterial.roughness = 0.55;
  frameMaterial.metalness = 0.5;
  frameMaterial.clearcoat = 0.2;
  const frameMesh = new Mesh(frameGeo, frameMaterial);
  frameMesh.position.z = -frameDepth * 0.5;
  inner.add(frameMesh);

  // ---- rim light local to this element (accent-hued back light) ----
  const rimLight = new PointLight(palette.accent, 0.8, 6);
  rimLight.position.set(-1.1, 0.9, -0.6);
  inner.add(rimLight);

  // ---- decorative image plane (subject depth plane) -----------------
  const faceW = cardW - 0.16;
  const faceH = cardH - 0.16;
  const faceGeo = new PlaneGeometry(faceW, faceH);
  const faceMaterial = new MeshBasicNodeMaterial();

  const placeholderTexture = new Texture();
  const faceUv = uv();

  const gradientNode = color(palette.surface).mix(color(palette.ink), faceUv.y);
  const grainSeed = dot(faceUv.mul(3200.0), vec2(12.9898, 78.233));
  const grain = fract(sin(grainSeed).mul(43758.5453)).sub(0.5).mul(0.035);

  const texNode = texture(placeholderTexture, faceUv);
  const blended = gradientNode.mix(texNode.rgb, texNode.a);
  faceMaterial.colorNode = blended.add(grain);

  const faceMesh = new Mesh(faceGeo, faceMaterial);
  faceMesh.position.z = frameDepth * 0.5 + 0.02;
  inner.add(faceMesh);

  let loadedTexture = null;
  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      loadedTexture = tex;
      texNode.value = tex;
    });
  }

  // ---- thin accent stripe, foreground depth plane, <=10% of frame ---
  const accentGeo = new BoxGeometry(cardW * 0.9, 0.055, 0.02);
  const accentMaterial = new MeshStandardNodeMaterial();
  accentMaterial.colorNode = color(palette.accent);
  accentMaterial.emissiveNode = color(palette.accent).mul(1.1);
  accentMaterial.roughness = 0.5;
  accentMaterial.metalness = 0.3;
  const accentMesh = new Mesh(accentGeo, accentMaterial);
  accentMesh.position.set(0, -cardH * 0.5 + 0.05, frameDepth * 0.5 + 0.05);
  inner.add(accentMesh);

  // ---- drop / contact shadow behind the card -------------------------
  const shadowRadius = cardW * 0.65;
  const shadowGeo = new PlaneGeometry(shadowRadius * 2, shadowRadius * 2);
  const shadowMaterial = new MeshBasicNodeMaterial();
  shadowMaterial.transparent = true;
  const shadowUv = uv();
  const dist = length(shadowUv.sub(vec2(0.5, 0.5)));
  shadowMaterial.colorNode = color('#000000');
  shadowMaterial.opacityNode = smoothstep(0.5, 0.0, dist).mul(0.45);
  const shadowMesh = new Mesh(shadowGeo, shadowMaterial);
  shadowMesh.position.z = -frameDepth * 0.5 - 0.4;
  inner.add(shadowMesh);

  // ---- primitives (none specified, iterate defensively) --------------
  const primitiveHandles = [];
  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    const fn = ctx.primitives?.[p.name];
    if (typeof fn === 'function') {
      const handle = fn(inner, p.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- weighted-settle entrance motion --------------------------------
  inner.scale.set(0.92, 0.92, 0.92);
  const startY = inner.position.y - 0.28;
  inner.position.y = startY;

  const tl = gsap.timeline();
  tl.to(inner.position, {
    y: startY + 0.28,
    duration: 0.7,
    ease: 'power3.out',
  }, 0)
    .to(inner.scale, {
      x: 1.04,
      y: 1.04,
      z: 1.04,
      duration: 0.42,
      ease: 'power2.out',
    }, 0)
    .to(inner.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.48,
      ease: 'power4.out',
    }, 0.42);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    tl.kill();
    for (const handle of primitiveHandles) {
      handle.cleanup?.();
    }
    inner.remove(rimLight);

    frameGeo.dispose();
    faceGeo.dispose();
    accentGeo.dispose();
    shadowGeo.dispose();

    frameMaterial.dispose();
    faceMaterial.dispose();
    accentMaterial.dispose();
    shadowMaterial.dispose();

    placeholderTexture.dispose();
    if (loadedTexture) loadedTexture.dispose();
  };

  return root;
}
